import json, re, os
from pathlib import Path
root=Path('/mnt/data/romueq_fix')
p=root/'docs/development/tasks/tasks.json'
d=json.loads(p.read_text())
tasks=d if isinstance(d,list) else d['tasks']

common_forbidden=['.git/','target/']
base_evidence=[
 'docs/development/evidence/<TASK_ID>-implementation.md',
 'docs/development/evidence/<TASK_ID>-tests.md',
 'docs/development/evidence/<TASK_ID>-evidence.md',
]

specs={}
def add(ids, purpose, pre, steps, tests, cmds, acc, paths, forbidden=common_forbidden, evidence=None, stop=None, rollback=None):
    for tid in ids:
        specs[tid]=dict(purpose=purpose,pre=pre,steps=steps,tests=tests,cmds=cmds,acc=acc,paths=paths,forbidden=forbidden,evidence=evidence or base_evidence,stop=stop or ['Required behavior cannot be demonstrated.','A P0 contract would need to change.','A new dependency or unsafe boundary is required without approval.'],rollback=rollback or 'Revert only this task\'s changes; preserve prior passing evidence and return the task to BLOCKED or TESTING as appropriate.')

add(['M1-T001'], 'Make the build environment explicit and reproducible before implementation.', ['M0.5 gate PASS; repository checkout is clean enough to inspect.'], ['Inspect rust-toolchain.toml, root Cargo.toml and every workspace manifest.','Pin an exact Rust toolchain version; do not silently change edition/resolver/package policy.','Ensure the workspace contains exactly the planned crates and no accidental members.','Ensure Cargo.lock policy is explicit and the lockfile is generated when appropriate for the workspace.','Document required rustfmt/clippy/toolchain components and local setup.','Record any unavailable local command as missing evidence rather than fabricating a result.'], ['Workspace membership check; manifest parse; format/clippy/test smoke when toolchain is available.'], ['rustc --version','cargo --version','cargo metadata --no-deps --format-version 1','cargo fmt --all -- --check','cargo clippy --workspace --all-targets --all-features -- -D warnings','cargo test --workspace --all-features'], ['Exact toolchain is pinned.','Workspace membership is deterministic.','No placeholder repository identity is invented.','The documented commands are runnable in the supported environment or explicitly marked pending external execution.','No architecture is changed merely to satisfy tooling.'], ['Cargo.toml','rust-toolchain.toml','Cargo.lock','docs/development/'], stop=['A required Rust version cannot build the declared edition/dependencies.','Changing resolver/edition requires an unrecorded architecture/toolchain decision.'])
add(['M1-T002'], 'Create a CI ladder that fails early and makes every quality gate reproducible.', ['M1-T001 DONE.'], ['Define formatting, compile, clippy, unit/integration tests, dependency checks and platform jobs in increasing cost order.','Pin action versions/major versions according to repository policy.','Make failures visible and non-optional for P0 checks.','Separate fast PR checks from scheduled/nightly checks without weakening PR gates.','Store machine-readable reports where practical.'], ['CI syntax validation; local equivalent commands; intentional failure test on a disposable branch if feasible.'], ['cargo fmt --all -- --check','cargo check --workspace --all-targets --all-features','cargo clippy --workspace --all-targets --all-features -- -D warnings','cargo test --workspace --all-features'], ['PR CI executes required P0 checks.','A failing P0 job blocks merge.','Nightly jobs do not masquerade as release gates.','Evidence paths are documented.'], ['.github/workflows/','docs/development/'], evidence=['docs/development/evidence/<TASK_ID>-implementation.md','docs/development/evidence/<TASK_ID>-tests.md','docs/development/evidence/ci-run-<TASK_ID>.md'])
add(['M1-T003'], 'Enforce dependency, advisory, license and source policies before third-party code accumulates.', ['M1-T002 DONE; LICENSING_DEPENDENCY_POLICY is authoritative.'], ['Install/configure cargo-deny or equivalent only if allowed by policy.','Validate licenses, advisories, bans, duplicate versions and source origins.','Add dependency review for changes.','Record every exception through Decision Request rather than configuration drift.'], ['Dependency audit; license audit; source policy audit.'], ['cargo deny check','cargo tree --workspace'], ['No forbidden license/source/dependency class passes.','All exceptions are explicitly recorded.','Audit output is retained as evidence.'], ['deny.toml','.github/','docs/development/'])
add(['M1-T004'], 'Make the frozen platform baseline executable in CI/build scripts.', ['M1-T003 DONE; accepted platform baseline from M0.'], ['Define jobs for macOS ARM64/x64, Windows x64 and Linux x64.','Use only targets that are actually supported by the chosen toolchain/dependencies.','Build all core crates on each target; adapters may remain compile-only until their milestone.','Document runner/host limitations and do not claim host compatibility from cross-compilation alone.'], ['Per-target cargo check/test where available; artifact metadata inspection.'], ['cargo build --workspace --all-targets','cargo test --workspace --all-features'], ['All baseline targets compile.','Unsupported test execution is explicitly marked as such.','No unverified DAW compatibility is claimed.'], ['.github/workflows/','docs/development/','scripts/'])
add(['M1-T005'], 'Close M1 with a reproducible repository/toolchain evidence package.', ['M1-T001..T004 DONE.'], ['Run the M1 checklist from clean checkout.','Collect versions, metadata, CI results, dependency audit and target results.','Update execution state, traceability and risk register.','Mark only demonstrated criteria PASS.'], ['Full M1 validation ladder.'], ['python3 scripts/validate_m05.py','cargo fmt --all -- --check','cargo clippy --workspace --all-targets --all-features -- -D warnings','cargo test --workspace --all-features'], ['All M1 P0 criteria PASS.','Evidence references resolve.','Next READY task is M2-T001 only after the gate.'], ['docs/development/'])

add(['M2-T001'], 'Empirically select and validate the bounded control-thread parameter transport without changing the public contract.', ['M1 gate PASS; ADR-001 remains Proposed.'], ['Implement at least two candidate bounded SPSC designs if needed for comparison.','Measure ordering, capacity, overwrite/drop behavior, producer/consumer contention and latency.','Define deterministic overflow semantics.','Prove no allocation/blocking on the audio consumer side.','Prepare DR-2026-002 recommendation; do not freeze implementation before evidence.'], ['Concurrency stress; overflow; ordering; model checking where practical; allocation checks.'], ['cargo test -p romueq-engine --all-features','cargo test --workspace --all-features'], ['Exactly one implementation is recommended with evidence.','Overflow is deterministic.','No audio-thread allocation/blocking.','ADR-001 can be updated only after the required decision is accepted.'], ['crates/romueq-engine/','docs/development/','docs/decisions/'], stop=['Candidate designs are indistinguishable without a human/product decision.','Queue semantics would contradict stable parameter behavior.'], evidence=['docs/development/evidence/<TASK_ID>-implementation.md','docs/development/evidence/<TASK_ID>-tests.md','docs/development/evidence/<TASK_ID>-benchmark.md','docs/development/evidence/<TASK_ID>-decision-input.md'])
