# Generate manual.
order=[t['id'] for t in tasks if t['id'].startswith('M') and not t['id'].startswith('M0') and t['id'] in specs]
from collections import defaultdict
by=defaultdict(list)
for tid in order: by[tid.split('-')[0]].append(tid)
milestone_names={
'M1':'Repository, toolchain, CI','M2':'P0 architecture prototypes','M3':'DSP mathematical foundation','M4':'Real-time engine','M5':'Analysis pipeline','M6':'GUI and interaction model','M7':'Plugin adapters','M8':'Standalone + CLI','M9':'Compatibility and hostile-host testing','M10':'Performance, reliability, hardening','M11':'Release candidate'}
lines=['# RomuEq — Local Execution Manual (M1 → M11)','', '**Purpose:** make the remaining implementation executable by a local human or AI agent without relying on undocumented conversation context.','', '> This manual expands the controlled task registry. The registry, MASTER_PLAN, accepted ADRs and product contracts remain authoritative. This document never authorizes silent changes to unresolved P0 decisions.','', '## 0. Operating contract','', '### 0.1 Before every task','1. Read `docs/development/EXECUTION_STATE.md`.','2. Select the first `READY` task in dependency order.','3. Read this manual section, the corresponding task entry in `tasks.json`, and all linked ADR/product contracts.','4. Verify the working tree and toolchain.','5. Change only allowed paths.','6. Implement the smallest coherent change that satisfies the task.','7. Run the task tests, then the standard regression ladder.','8. Generate the evidence files named by the task.','9. Update traceability, risks and execution state.','10. Only then change the task to `DONE`.','', '### 0.2 Mandatory stop conditions','- Missing/contradictory P0 decision.','- Need to change an accepted product/parameter/state contract without a new decision.','- New dependency outside `LICENSING_DEPENDENCY_POLICY.md`.','- New unsafe code outside an approved adapter boundary.','- Allocation/blocking/I/O/syscall/panic in the audio hot path.','- Host behavior contradicts an assumption and no contract exists.','- Acceptance criterion cannot be objectively demonstrated.','- Test failure is flaky, unexplained or non-reproducible.','- Evidence cannot be reproduced from the documented environment.','', '### 0.3 Evidence naming','For each task, create:','- `docs/development/evidence/<TASK-ID>-implementation.md`','- `docs/development/evidence/<TASK-ID>-tests.md`','- `docs/development/evidence/<TASK-ID>-evidence.md`','Additional benchmark/decision/host evidence is listed in the task section.','', '### 0.4 Standard evidence record','```text','Task: <ID>','Commit/source revision: <value>','Environment: <OS/arch/toolchain>','Commands: <exact commands>','Results: PASS/FAIL','Artifacts: <paths>','Acceptance: criterion-by-criterion PASS/FAIL','Risks changed: <IDs>','Decisions changed: <DR/ADR IDs>','Known limitations: <none or explicit>','```','', '## 1. Global quality gates','', '| Area | Minimum evidence | Blocking rule |','|---|---|---|','| Build | workspace compiles on declared targets | P0 failure blocks |','| Format | rustfmt clean | P0 failure blocks |','| Clippy | `-D warnings` clean | P0 failure blocks |','| Tests | workspace regression green | P0 failure blocks |','| RT safety | zero process allocations + no blocking/I/O/panic | P0 failure blocks |','| DSP | reference/property/stability evidence | P0 failure blocks |','| Compatibility | exact host/version matrix | P0 failure blocks |','| Security | dependency/license/advisory/source checks | P0 failure blocks |','| Release | reproducible packages + clean-machine smoke | P0 failure blocks |','', '## 2. Detailed task execution specifications','']
for m in [f'M{i}' for i in range(1,12)]:
    lines += [f'### {m} — {milestone_names[m]}','']
    for tid in by[m]:
        s=specs[tid]; t=next(x for x in tasks if x['id']==tid)
        lines += [f'#### {tid} — {t["title"]}','',f'**Priority:** {t["priority"]}  ',f'**Dependencies:** {", ".join(t["deps"]) or "none"}  ',f'**Decision dependencies:** {", ".join(t["decisions"]) or "none"}  ',f'**Human decision:** {t["human"]}  ','',f'**Purpose**  {s["purpose"]}','', '**Preconditions**']
        lines += [f'- {x}' for x in s['pre']]
        lines += ['', '**Implementation procedure**']
        lines += [f'{i}. {x}' for i,x in enumerate(s['steps'],1)]
        lines += ['', '**Tests**']+[f'- {x}' for x in s['tests']]
        lines += ['', '**Validation commands**','```bash']+s['cmds']+['```','', '**Acceptance — all must be PASS**']+[f'- [ ] {x}' for x in s['acc']]
        lines += ['', '**Allowed paths**']+[f'- `{x}`' for x in s['paths']]
        lines += ['', '**Forbidden paths**']+[f'- `{x}`' for x in s['forbidden']]
        lines += ['', '**Evidence**']+[f'- `{x.replace("<TASK_ID>",tid)}`' for x in s['evidence']]
        lines += ['', '**STOP-THE-LINE if**']+[f'- {x}' for x in s['stop']]
        lines += ['', '**Rollback / failure handling**',s['rollback'],'', '**Definition of DONE**'] + [f'- {x}' for x in ['Implementation complete','Tests PASS','Acceptance criteria PASS','Evidence complete','Traceability/risk/state updated','No unresolved stop condition']] + ['']

